begin;
-- 博客作品独立保存，前台只读取已发布项目；写入由 Supabase 后台管理。
create table public.blog_works (id bigint generated always as identity primary key, sort_order integer not null default 0, published boolean not null default true, data jsonb not null check (jsonb_typeof(data)='object'), updated_at timestamptz not null default now());
alter table public.blog_works enable row level security;
revoke all on public.blog_works from public, anon, authenticated;
grant select on public.blog_works to anon, authenticated;
create policy blog_works_public_read on public.blog_works for select to anon, authenticated using (published = true);
commit;
